# faymcp/prestart_registry.py
def set_prestart(server_id, tool_name, params, include_history=True, allow_function_call=False):
    server_map = _prestart.setdefault(int(server_id), {})
    server_map[str(tool_name)] = {
        "params": params or {},
        "include_history": include_history,
        "allow_function_call": allow_function_call,
    }
    _save_locked()

# llm/nlp_cognitive_stream.py
def _run_prestart_tools(user_question):
    tools = mcp_runtime.list_runnable_prestart_tools()
    results = []
    for item in tools:
        params = item.get("params") or {}
        include_history = item.get("include_history", True)
        filled_params = _apply_question_placeholder(params, user_question)

        success, result = mcp_runtime.call_tool(
            int(item["server_id"]), item["tool"],
            filled_params, skip_enabled_check=True,
        )
        if success:
            output = _normalize_tool_output(result)
            params_str = "(" + ", ".join(f"{k}={v}" for k, v in filled_params.items()) + ")"
            results.append({
                "text": f"【{item['tool']}】{params_str}\n{output.strip()}",
                "include_history": include_history,
            })
    return results

