# core/fay_core.py
def __has_prestart(self, text):
    return re.search(r'<prestart[^>]*>[\s\S]*?</prestart>', text,
                     flags=re.IGNORECASE) is not None

def __remove_prestart_tags(self, text):
    cleaned = re.sub(r'<prestart[^>]*>[\s\S]*?</prestart>', '', text,
                     flags=re.IGNORECASE)
    return cleaned.strip()

